{[Fact] public void PaperRetainsRawConstructorsUntilZeroCallerProof(){string p=File.ReadAllText(Path.Combine(Root(),"ResearchPaper","section","md base","7_Replay_Stable_Placement_Replay_Tokens_and_Execution_Boundaries.md"));Assert.Contains("while production loop-buffer",p,StringComparison.Ordinal);Assert.Contains("TestAssembler diagnostics retain nonzero",p,StringComparison.Ordinal);Assert.Contains("no removal, checked-overload rebinding",p,StringComparison.Ordinal);Assert.Contains("zero-caller proof",p,StringComparison.Ordinal);Assert.Contains("cannot allocate an epoch",p,StringComparison.Ordinal);}private static string Root(){DirectoryInfo? c=new(AppContext.BaseDirectory);while(c is not null){if(Directory.Exists(Path.Combine(c.FullName,"ResearchPaper")))return c.FullName;c=c.Parent;}throw new DirectoryNotFoundException();}}
